country_event = {
	id = cstorms.240

	is_triggered_only = yes
	hide_window = yes

	immediate = {
		# Try to find a barren world in an adAkkaria system within our borders.

		if = {
			limit = {
				is_nomadic = no
			}
			random_system_within_border = {
				limit = {
					NOT = { has_star_flag = precursor_system }
					has_star_flag = precursor_adakkaria

					any_system_planet = {
						OR = {
							is_planet_class = pc_barren
							is_planet_class = pc_barren_cold
						}
						NOR = {
							has_carrier_flag = precursor_world
							exists = archaeological_site
						}
					}
				}

				save_event_target_as = system_windswept_fates
				prev = { set_country_flag = system_windswept_fates_found }
			}
			# Fallback to already used adakkaria system within borders
			if = {
				limit = { NOT = { has_country_flag = system_windswept_fates_found } }

				random_system_within_border = {
					limit = {
						has_star_flag = precursor_adakkaria

						any_system_planet = {
							OR = {
								is_planet_class = pc_barren
								is_planet_class = pc_barren_cold
							}
							NOR = {
								has_carrier_flag = precursor_world
								exists = archaeological_site
							}
						}
					}

					save_event_target_as = system_windswept_fates
					prev = { set_country_flag = system_windswept_fates_found }
				}
			}
			# Fallback to random system within borders
			if = {
				limit = { NOT = { has_country_flag = system_windswept_fates_found } }

				random_system_within_border = {
					limit = {
						any_system_planet = {
							OR = {
								is_planet_class = pc_barren
								is_planet_class = pc_barren_cold
							}
							NOR = {
								has_carrier_flag = precursor_world
								exists = archaeological_site
							}
						}
					}

					save_event_target_as = system_windswept_fates
				}
			}
		}
		else = {
			# Try to find a waystation in an adAkkaria system with a valid barren planet.
			if = {
				limit = {
					any_owned_nonprimary_starbase = {
						is_waystation_starbase = yes
						solar_system? = {
							NOT = { has_star_flag = precursor_system }
							has_star_flag = precursor_adakkaria
							any_system_planet = {
								OR = {
									is_planet_class = pc_barren
									is_planet_class = pc_barren_cold
								}
								NOR = {
									has_carrier_flag = precursor_world
									exists = archaeological_site
								}
							}
						}
					}
				}
				random_owned_nonprimary_starbase = {
					limit = {
						is_waystation_starbase = yes
						solar_system? = {
							NOT = { has_star_flag = precursor_system }
							has_star_flag = precursor_adakkaria
							any_system_planet = {
								OR = {
									is_planet_class = pc_barren
									is_planet_class = pc_barren_cold
								}
								NOR = {
									has_carrier_flag = precursor_world
									exists = archaeological_site
								}
							}
						}
					}
					solar_system = {
						save_event_target_as = system_windswept_fates
						ROOT = { set_country_flag = system_windswept_fates_found }
					}
				}
			}
			# Fallback to any adAkkaria waystation system.
			if = {
				limit = {
					NOT = { has_country_flag = system_windswept_fates_found }
					any_owned_nonprimary_starbase = {
						is_waystation_starbase = yes
						solar_system? = {
							has_star_flag = precursor_adakkaria
							any_system_planet = {
								OR = {
									is_planet_class = pc_barren
									is_planet_class = pc_barren_cold
								}
								NOR = {
									has_carrier_flag = precursor_world
									exists = archaeological_site
								}
							}
						}
					}
				}
				random_owned_nonprimary_starbase = {
					limit = {
						is_waystation_starbase = yes
						solar_system? = {
							has_star_flag = precursor_adakkaria
							any_system_planet = {
								OR = {
									is_planet_class = pc_barren
									is_planet_class = pc_barren_cold
								}
								NOR = {
									has_carrier_flag = precursor_world
									exists = archaeological_site
								}
							}
						}
					}
					solar_system = {
						save_event_target_as = system_windswept_fates
						ROOT = { set_country_flag = system_windswept_fates_found }
					}
				}
			}
			# Fallback to any waystation system with a barren planet.
			if = {
				limit = {
					NOT = { has_country_flag = system_windswept_fates_found }
					any_owned_nonprimary_starbase = {
						is_waystation_starbase = yes
						solar_system? = {
							any_system_planet = {
								OR = {
									is_planet_class = pc_barren
									is_planet_class = pc_barren_cold
								}
								NOR = {
									has_carrier_flag = precursor_world
									exists = archaeological_site
								}
							}
						}
					}
				}
				random_owned_nonprimary_starbase = {
					limit = {
						is_waystation_starbase = yes
						solar_system? = {
							any_system_planet = {
								OR = {
									is_planet_class = pc_barren
									is_planet_class = pc_barren_cold
								}
								NOR = {
									has_carrier_flag = precursor_world
									exists = archaeological_site
								}
							}
						}
					}
					solar_system = {
						save_event_target_as = system_windswept_fates
						ROOT = { set_country_flag = system_windswept_fates_found }
					}
				}
			}
			# Fallback: use the arkship's current system.
			if = {
				limit = {
					NOT = { has_country_flag = system_windswept_fates_found }
				}
				random_owned_colony = {
					limit = { exists = solar_system }
					solar_system = { save_event_target_as = system_windswept_fates }
					ROOT = { set_country_flag = system_windswept_fates_found }
				}
			}
			# Final Fallback
			if = {
				limit = {
					NOT = { has_country_flag = system_windswept_fates_found }
				}
				fromfrom.solar_system = {
					save_event_target_as = system_windswept_fates
					ROOT = { set_country_flag = system_windswept_fates_found }
				}
			}
		}

		event_target:system_windswept_fates = {
			# Spawn the storm.
			spawn_random_storm = {
				cosmic_storm_start_position = this
				immediate = yes
			}

			last_created_cosmic_storm = {
				set_storm_flag = storm_windswept_fates
				save_event_target_as = storm_windswept_fates
			}

			# We ensured in the previous event that this system has a matching planet.
			random_system_planet = {
				limit = {
					OR = {
						is_planet_class = pc_barren
						is_planet_class = pc_barren_cold
					}
					NOR = {
						has_carrier_flag = precursor_world
						exists = archaeological_site
					}
				}

				save_global_event_target_as = planet_windswept_fates
				mark_used_by_precursor = yes
			}
		}

		country_event = {
			id = cstorms.245
			days = 70
			random = 20
		}

		# Only needed during this event.
		remove_country_flag = system_windswept_fates_found
	}
}

