script:
fleet_event = {
	id = cstorms.2140
	title = cstorms.2140.name
	desc = cstorms.2140.desc
	event_chain = cs_adAkkaria_chain
	picture = GFX_evt_intelligence_report
	show_sound = event_scanner

	is_triggered_only = yes

	immediate = {
		owner = {
			if = {
				limit = { is_nomadic = no }
				random_system_within_border = {
					limit = {
						any_system_planet = {
							is_star = no
							NOR = {
								has_carrier_flag = precursor_world
								exists = archaeological_site
							}
						}
					}

					weights = {
						base = 1

						# Prefer not to use a system already usedfor a precursor event/
						modifier = {
							has_star_flag = precursor_system
							factor = 0.001
						}

						# heavily prefer adakkaria systems.
						modifier = {
							has_star_flag = precursor_adakkaria
							factor = 100
						}

						# Really want systems with asteroid belts
						modifier = {
							num_asteroid_belts > 0
							factor = 100
						}
					}

					random_system_planet = {
						limit = {
							is_star = no
							NOR = {
								has_carrier_flag = precursor_world
								exists = archaeological_site
							}
						}

						weights = {
							base = 1

							# prefer asteroids
							modifier = {
								is_asteroid = yes
								factor = 100
							}
						}

						save_event_target_as = planet_storm_to_signal
					}
				}
			}
			else = {
				if = {
					limit = {
						any_owned_nonprimary_starbase = {
							is_waystation_starbase = yes
							solar_system? = {
								any_system_planet = {
									is_star = no
									NOR = {
										has_carrier_flag = precursor_world
										exists = archaeological_site
									}
								}
							}
						}
					}
					random_owned_nonprimary_starbase = {
						limit = {
							is_waystation_starbase = yes
							solar_system? = {
								any_system_planet = {
									is_star = no
									NOR = {
										has_carrier_flag = precursor_world
										exists = archaeological_site
									}
								}
							}
						}
						weights = {
							base = 1
							modifier = {
								add = 2
								has_starbase_size = starbase_waystation_2
							}
							modifier = {
								add = 4
								has_starbase_size = starbase_waystation_3
							}
							modifier = {
								add = 5
								solar_system? = { any_fleet_in_system = { is_arkship_fleet = yes } }
							}
							modifier = {
								factor = 0.001
								solar_system? = { has_star_flag = precursor_system }
							}
							modifier = {
								factor = 100
								solar_system? = { has_star_flag = precursor_adakkaria }
							}
							modifier = {
								factor = 100
								solar_system? = { num_asteroid_belts > 0 }
							}
						}
						solar_system? = {
							random_system_planet = {
								limit = {
									is_star = no
									NOR = {
										has_carrier_flag = precursor_world
										exists = archaeological_site
									}
								}
								weights = {
									base = 1
									modifier = {
										is_asteroid = yes
										factor = 100
									}
								}
								save_event_target_as = planet_storm_to_signal
							}
						}
					}
				}
				# Fallback: use the arkship's current system.
				else = {
					random_owned_starbase = {
						limit = {
							is_arkship_starbase = yes
							exists = solar_system
						}
						solar_system? = {
							random_system_planet = {
								limit = {
									is_star = no
									NOR = {
										has_carrier_flag = precursor_world
										exists = archaeological_site
									}
								}
								weights = {
									base = 1
									modifier = {
										is_asteroid = yes
										factor = 100
									}
								}
								save_event_target_as = planet_storm_to_signal
							}
						}
					}
				}
				# Final Fallback
				if = {
					limit = {
						NOT = { exists = event_target:planet_storm_to_signal }
					}
					event_target:planet_windswept_fates = {
						solar_system? = {
							# Prefer a free, unused body in this system.
							if = {
								limit = {
									any_system_planet = {
										is_star = no
										NOR = {
											has_carrier_flag = precursor_world
											exists = archaeological_site
										}
									}
								}
								random_system_planet = {
									limit = {
										is_star = no
										NOR = {
											has_carrier_flag = precursor_world
											exists = archaeological_site
										}
									}
									weights = {
										base = 1
										modifier = {
											is_asteroid = yes
											factor = 100
										}
									}
									save_event_target_as = planet_storm_to_signal
								}
							}
							# Otherwise an adjacent system with a free body.
							else = {
								random_neighbor_system = {
									limit = {
										any_system_planet = {
											is_star = no
											NOR = {
												has_carrier_flag = precursor_world
												exists = archaeological_site
											}
										}
									}
									random_system_planet = {
										limit = {
											is_star = no
											NOR = {
												has_carrier_flag = precursor_world
												exists = archaeological_site
											}
										}
										weights = {
											base = 1
											modifier = {
												is_asteroid = yes
												factor = 100
											}
										}
										save_event_target_as = planet_storm_to_signal
									}
								}
							}
						}
					}
				}
			}
		}
	}

	option = {
		name = EXCELLENT

		event_target:planet_storm_to_signal = {
			hidden_effect = { mark_used_by_precursor = yes }
			create_archaeological_site = site_adakkaria_fleets_of_the_thrice_damned
		}
	}

	after = {
		# Remove flag, was only necessary locally to track if a system with asteroids was found.
		owner = {
			remove_country_flag = planet_storm_to_signal_found
		}
	}
}

